create or replace function reap_stale_schedule_worker_attempts_v1() returns integer language plpgsql security definer set search_path=public as $$declare r record;n int:=0;nw uuid;nk text;begin if auth.role()<>'service_role' then raise exception 'SERVICE_ROLE_REQUIRED';end if;for r in select a.id,a.job_id,w.id wid,w.worker_type,w.worker_key from schedule_solve_attempts a join schedule_compute_workers w on w.id=a.worker_id where a.status='RUNNING' and w.worker_type in('CPU','GPU') and (not w.active or w.health in('OFFLINE','UNKNOWN') or w.last_heartbeat is null or w.last_heartbeat<=now()-interval '5 minutes') for update of a skip locked loop select x.id,x.worker_key into nw,nk from schedule_compute_workers x where x.active and x.id<>r.wid and x.health in('HEALTHY','DEGRADED') and (x.worker_key='db-native' or x.last_heartbeat>now()-interval '5 minutes') and (x.worker_type=r.worker_type or (r.worker_type='GPU' and x.worker_type='CPU') or x.worker_type='DB') order by case when x.worker_type=r.worker_type then 0 when r.worker_type='GPU' and x.worker_type='CPU' then 1 when x.worker_type='DB' then 2 else 9 end,x.current_load,x.priority limit 1;if nw is not null then update schedule_solve_attempts set worker_id=nw,status='PLANNED',started_at=null,finished_at=null,diagnostics=coalesce(diagnostics,'{}')||jsonb_build_object('reaped_from',r.worker_key,'reaped_at',now()) where id=r.id;else update schedule_solve_attempts set status='FAILED',finished_at=now(),diagnostics=coalesce(diagnostics,'{}')||jsonb_build_object('stale_worker',r.worker_key,'failed_at',now()) where id=r.id;end if;n:=n+1;end loop;update schedule_solve_jobs j set status=case when exists(select 1 from schedule_solve_attempts a where a.job_id=j.id and a.status='COMPLETED') then 'PARTIAL' else 'FAILED' end,finished_at=now() where j.status='RUNNING' and not exists(select 1 from schedule_solve_attempts a where a.job_id=j.id and a.status in('PLANNED','RUNNING'));return n;end$$;